import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.B5WAEDB7.js";const c=JSON.parse('{"title":"Anmeldung mit Microsoft","description":"ApptiveGrid in Microsoft Entra als Unternehmensanwendung freigeben — für Nutzer und IT-Administration.","frontmatter":{"title":"Anmeldung mit Microsoft","description":"ApptiveGrid in Microsoft Entra als Unternehmensanwendung freigeben — für Nutzer und IT-Administration."},"headers":[],"relativePath":"erste-schritte/anmeldung-mit-microsoft.md","filePath":"erste-schritte/anmeldung-mit-microsoft.md","lastUpdated":1787814657000}'),a={name:"erste-schritte/anmeldung-mit-microsoft.md"};function d(s,e,o,l,g,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="anmeldung-mit-microsoft" tabindex="-1">Anmeldung mit Microsoft <a class="header-anchor" href="#anmeldung-mit-microsoft" aria-label="Permalink to &quot;Anmeldung mit Microsoft&quot;">​</a></h1><p>ApptiveGrid lässt sich mit einem bestehenden Microsoft-Konto nutzen — über die Schaltfläche <strong>Mit Microsoft anmelden</strong> auf der Anmeldeseite. Ein eigenes Passwort wird dabei nicht vergeben.</p><p>Bei <strong>Geschäfts- und Schulkonten</strong> entscheidet die IT der eigenen Organisation, welche fremden Anwendungen sich anmelden dürfen. Ist das eingeschränkt, kann die Anmeldung mit <em>Genehmigung erforderlich</em> abbrechen. Es liegt dann nicht an Ihrem Konto, sondern an einer fehlenden Freigabe in <strong>Microsoft Entra</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Diese Seite ist zum Weitergeben gedacht</p><p>Sie können sie unverändert an Ihre IT-Abteilung schicken. Der zweite Teil enthält alles, was dort für die Entscheidung gebraucht wird: angefragte Berechtigungen, Anwendungs-ID und den Weg durch das Microsoft-Entra-Portal.</p></div><h2 id="fur-nutzer" tabindex="-1">Für Nutzer <a class="header-anchor" href="#fur-nutzer" aria-label="Permalink to &quot;Für Nutzer&quot;">​</a></h2><ol><li>Rufen Sie <a href="https://app.apptivegrid.de" target="_blank" rel="noreferrer">app.apptivegrid.de</a> auf und wählen Sie <strong>Mit Microsoft anmelden</strong>.</li><li>Erscheint <em>Genehmigung erforderlich</em>, lässt sich die Anfrage — sofern Ihre Organisation das anbietet — direkt aus dem Dialog mit einer Begründung an die Administration schicken.</li><li>Bietet der Dialog das nicht an, wenden Sie sich an Ihre IT-Abteilung und geben Sie diese Seite weiter.</li></ol><p>Sobald die Freigabe erteilt ist, können sich grundsätzlich auch weitere Personen Ihrer Organisation anmelden. Ihre IT kann den Zugriff zusätzlich auf bestimmte Benutzer oder Gruppen beschränken; ist in Microsoft Entra <em>Zuweisung erforderlich</em> aktiviert, gilt die Anmeldung nur für die dort zugewiesenen Personen.</p><p>Erscheint stattdessen <em>Leider können wir Sie nicht anmelden</em> mit einem Code wie <code>AADSTS7000112</code>, ist ApptiveGrid in Ihrer Organisation ausdrücklich gesperrt. Auch das lässt sich nur dort aufheben — geben Sie ebenfalls diese Seite weiter.</p><div class="warning custom-block"><p class="custom-block-title">Immer denselben Weg nehmen</p><p>Ein über Microsoft angelegtes Konto hat bei ApptiveGrid kein eigenes Passwort. Melden Sie sich später immer über dieselbe Schaltfläche an. → <a href="/erste-schritte/konto-und-anmeldung">Konto und Anmeldung</a></p></div><hr><h2 id="fur-die-it-administration" tabindex="-1">Für die IT-Administration <a class="header-anchor" href="#fur-die-it-administration" aria-label="Permalink to &quot;Für die IT-Administration&quot;">​</a></h2><p>ApptiveGrid ist eine Anwendung zum Erfassen, Auswerten und Teilen strukturierter Daten (Betreiber: ApptiveGrid GmbH). Für die Anmeldung nutzt sie Microsoft Entra ID als Identitätsanbieter im üblichen OpenID-Connect-Verfahren.</p><p><strong>Das Microsoft-Passwort wird nicht an ApptiveGrid übertragen.</strong> Die Anmeldung findet vollständig bei Microsoft statt. Zurück kommen die für die Identifikation erforderlichen OpenID-Connect-Informationen: eine Benutzerkennung, der Name und — sofern in Microsoft Entra hinterlegt — die E-Mail-Adresse.</p><h3 id="was-angefragt-wird" tabindex="-1">Was angefragt wird <a class="header-anchor" href="#was-angefragt-wird" aria-label="Permalink to &quot;Was angefragt wird&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Anwendungs-ID (Client-ID)</td><td><code>c5bf8ba8-b06b-4d90-a16b-3598f50d9950</code></td></tr><tr><td>Berechtigungen</td><td><code>openid</code>, <code>profile</code>, <code>email</code></td></tr><tr><td>Antwort-URL</td><td><code>https://app.apptivegrid.de/auth/callback/microsoft</code></td></tr><tr><td>Verfahren</td><td>OpenID Connect, Authorization Code</td></tr></tbody></table><p>Das sind die drei Standard-Bereiche für eine reine Anmeldung:</p><table tabindex="0"><thead><tr><th>Berechtigung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>openid</code></td><td>Benutzer sicher identifizieren und anmelden</td></tr><tr><td><code>profile</code></td><td>Grundlegende Profilinformationen des angemeldeten Benutzers</td></tr><tr><td><code>email</code></td><td>E-Mail-Adresse, sofern von Microsoft verfügbar</td></tr></tbody></table><p>ApptiveGrid erhält damit keinen Zugriff auf Postfächer, Dateien, Kalender oder Teams und kann keine Microsoft-365-Daten über Microsoft Graph lesen oder verändern.</p><h3 id="welche-meldung-liegt-vor" tabindex="-1">Welche Meldung liegt vor <a class="header-anchor" href="#welche-meldung-liegt-vor" aria-label="Permalink to &quot;Welche Meldung liegt vor&quot;">​</a></h3><p>Es sind drei verschiedene Fälle, die drei verschiedene Handgriffe brauchen:</p><table tabindex="0"><thead><tr><th>Meldung</th><th>Ursache</th><th>Abhilfe</th></tr></thead><tbody><tr><td><em>Genehmigung erforderlich</em> — <code>AADSTS90094</code></td><td>Die Einwilligung der Administration fehlt</td><td>Wege 1 bis 3</td></tr><tr><td><em>Application &#39;…&#39; (ApptiveGrid) is disabled</em> — <code>AADSTS7000112</code></td><td>Der Eintrag besteht, ist aber für die Anmeldung gesperrt</td><td><a href="#gesperrte-anwendung-freischalten">Gesperrte Anwendung freischalten</a></td></tr><tr><td><em>… is not assigned to a role for the application</em> — <code>AADSTS50105</code></td><td><em>Zuweisung erforderlich</em> steht auf <strong>Ja</strong>, die Person ist aber nicht zugewiesen</td><td><a href="#auf-bestimmte-personen-begrenzen">Auf bestimmte Personen begrenzen</a></td></tr></tbody></table><h3 id="warum-die-einwilligung-fehlt" tabindex="-1">Warum die Einwilligung fehlt <a class="header-anchor" href="#warum-die-einwilligung-fehlt" aria-label="Permalink to &quot;Warum die Einwilligung fehlt&quot;">​</a></h3><p>In vielen Organisationen ist die Benutzereinwilligung für externe Anwendungen eingeschränkt oder vollständig deaktiviert — einzustellen unter <em>Unternehmensanwendungen</em> → <strong>Einwilligung und Berechtigungen</strong>. In diesem Fall kann eine Administratoreinwilligung für ApptiveGrid erforderlich sein. In den Anmeldeprotokollen erscheint der Fall typischerweise als <code>AADSTS90094</code>.</p><h3 id="weg-1-·-offene-anfrage-genehmigen" tabindex="-1">Weg 1 · Offene Anfrage genehmigen <a class="header-anchor" href="#weg-1-·-offene-anfrage-genehmigen" aria-label="Permalink to &quot;Weg 1 · Offene Anfrage genehmigen&quot;">​</a></h3><p>Hat jemand die Anfrage aus dem Anmeldedialog abgeschickt, liegt sie im <a href="https://entra.microsoft.com" target="_blank" rel="noreferrer">Microsoft Entra Admin Center</a> unter <strong>Identität</strong> → <strong>Anwendungen</strong> → <strong>Unternehmensanwendungen</strong> → <em>Administratoreinwilligungsanfragen</em>.</p><h3 id="weg-2-·-direkt-freigeben" tabindex="-1">Weg 2 · Direkt freigeben <a class="header-anchor" href="#weg-2-·-direkt-freigeben" aria-label="Permalink to &quot;Weg 2 · Direkt freigeben&quot;">​</a></h3><p><strong>Unternehmensanwendungen</strong> → <strong>ApptiveGrid</strong> → <em>Berechtigungen</em> → <strong>Administratoreinwilligung für {Organisation} erteilen</strong>.</p><h3 id="weg-3-·-wenn-apptivegrid-noch-nicht-im-verzeichnis-steht" tabindex="-1">Weg 3 · Wenn ApptiveGrid noch nicht im Verzeichnis steht <a class="header-anchor" href="#weg-3-·-wenn-apptivegrid-noch-nicht-im-verzeichnis-steht" aria-label="Permalink to &quot;Weg 3 · Wenn ApptiveGrid noch nicht im Verzeichnis steht&quot;">​</a></h3><p>Hat es noch niemand versucht, gibt es auch noch keinen Eintrag. Dieser Aufruf legt ihn an und erteilt die Einwilligung in einem Schritt — <code>&lt;mandant&gt;</code> ist die Mandanten-ID oder der Domänenname:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://login.microsoftonline.com/&lt;mandant&gt;/adminconsent?client_id=c5bf8ba8-b06b-4d90-a16b-3598f50d9950</span></span></code></pre></div><h3 id="gesperrte-anwendung-freischalten" tabindex="-1">Gesperrte Anwendung freischalten <a class="header-anchor" href="#gesperrte-anwendung-freischalten" aria-label="Permalink to &quot;Gesperrte Anwendung freischalten&quot;">​</a></h3><blockquote><p><em>AADSTS7000112: Application &#39;c5bf8ba8-b06b-4d90-a16b-3598f50d9950&#39; (ApptiveGrid) is disabled.</em></p></blockquote><p>Hier fehlt keine Einwilligung. ApptiveGrid steht bereits im Verzeichnis, die Anmeldung ist für den Eintrag aber abgeschaltet. Der Schalter dafür:</p><p><strong>Unternehmensanwendungen</strong> → <strong>ApptiveGrid</strong> → <em>Eigenschaften</em> → <strong>Für Benutzer aktiviert zum Anmelden?</strong> auf <strong>Ja</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Die Sperre ist eine Entscheidung, kein Fehler</p><p>Der Schalter steht nicht von selbst auf <em>Nein</em>. Klären Sie im Team, ob die Anwendung bewusst gesperrt wurde — etwa im Rahmen einer Richtlinie zur App-Steuerung —, bevor Sie ihn umlegen.</p></div><p>Die Sperre gilt nur im eigenen Mandanten. Für Nutzer sieht sie wie ein Ausfall bei ApptiveGrid aus, obwohl sich außerhalb der Organisation nichts geändert hat.</p><h3 id="auf-bestimmte-personen-begrenzen" tabindex="-1">Auf bestimmte Personen begrenzen <a class="header-anchor" href="#auf-bestimmte-personen-begrenzen" aria-label="Permalink to &quot;Auf bestimmte Personen begrenzen&quot;">​</a></h3><p>Die Einwilligung gilt zunächst für die gesamte Organisation. Soll nur ein Teil der Belegschaft ApptiveGrid nutzen:</p><p><strong>Unternehmensanwendungen</strong> → <strong>ApptiveGrid</strong> → <em>Eigenschaften</em> → <strong>Zuweisung erforderlich?</strong> auf <strong>Ja</strong>. Danach unter <em>Benutzer und Gruppen</em> die vorgesehenen Personen oder Gruppen zuweisen.</p><h3 id="zurucknehmen" tabindex="-1">Zurücknehmen <a class="header-anchor" href="#zurucknehmen" aria-label="Permalink to &quot;Zurücknehmen&quot;">​</a></h3><p><strong>Unternehmensanwendungen</strong> → <strong>ApptiveGrid</strong> → <em>Eigenschaften</em> → <strong>Löschen</strong>. Die Anmeldung über Microsoft ist damit sofort wieder gesperrt.</p><div class="tip custom-block"><p class="custom-block-title">Kosten entstehen auf Microsoft-Seite keine</p><p>Die Freigabe ist eine Einwilligung, keine Lizenz. Der Tarif von ApptiveGrid wird unabhängig davon je Space gebucht. → <a href="/zusammenarbeit/sitzplaetze">Sitzplätze</a></p></div><h3 id="benutzer-automatisch-bereitstellen-scim" tabindex="-1">Benutzer automatisch bereitstellen (SCIM) <a class="header-anchor" href="#benutzer-automatisch-bereitstellen-scim" aria-label="Permalink to &quot;Benutzer automatisch bereitstellen (SCIM)&quot;">​</a></h3><p>Über die Anmeldung hinaus unterstützt ApptiveGrid <strong>SCIM</strong>: Microsoft Entra legt die Benutzerkonten in ApptiveGrid selbst an und hält sie aktuell. Der Kontenbestand folgt dann dem Verzeichnis der Organisation, statt von Hand gepflegt zu werden.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Identity Provider</td><td>Microsoft Entra ID</td></tr><tr><td>Übertragen werden</td><td>Benutzer und Gruppen</td></tr><tr><td>Verfügbar im</td><td>Enterprise-Tarif</td></tr></tbody></table><p>Die Einrichtung erfolgt gemeinsam mit uns. Anfragen an <strong><a href="mailto:support@apptivegrid.de" target="_blank" rel="noreferrer">support@apptivegrid.de</a></strong>.</p><div class="tip custom-block"><p class="custom-block-title">Gruppen sind noch keine Berechtigung</p><p>Übernommene Organisationsgruppen stehen im Profil der jeweiligen Person. Der Zugriff auf einen Space wird weiterhin über <a href="/zusammenarbeit/rollen">Rollen</a> vergeben, nicht über die Gruppenzugehörigkeit.</p></div><h2 id="haufige-ruckfragen" tabindex="-1">Häufige Rückfragen <a class="header-anchor" href="#haufige-ruckfragen" aria-label="Permalink to &quot;Häufige Rückfragen&quot;">​</a></h2><p><strong>Sieht ApptiveGrid unsere Postfächer oder Dateien?</strong> Nein. Angefragt werden ausschließlich <code>openid</code>, <code>profile</code> und <code>email</code>; ein Zugriff über Microsoft Graph findet nicht statt.</p><p><strong>Werden Passwörter an ApptiveGrid übertragen?</strong> Nein. Die Anmeldung läuft vollständig bei Microsoft. Übermittelt werden nur die Anmeldebestätigung und die Angaben zur Identifikation des Benutzers.</p><p><strong>Legt die Freigabe automatisch Konten an?</strong> Sie erlaubt die Anmeldung. Ein ApptiveGrid-Konto entsteht erst, wenn sich eine Person tatsächlich anmeldet.</p><p><strong>Gilt das auch für private Microsoft-Konten?</strong> Nein. Die Einschränkung betrifft nur Geschäfts- und Schulkonten, die zu einem Entra-Mandanten gehören.</p><p><strong>Bei uns steht die Anwendung auf gesperrt — war das Microsoft?</strong> Nein. <em>Für Benutzer aktiviert zum Anmelden</em> wird im eigenen Mandanten gesetzt, von einer Person oder einer Richtlinie.</p><p><strong>Können wir die Freigabe später prüfen?</strong> Ja. Die Anwendung steht danach mit allen erteilten Berechtigungen unter <em>Unternehmensanwendungen</em>, die Anmeldungen im Anmeldeprotokoll.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/erste-schritte/konto-und-anmeldung">Konto und Anmeldung</a></li><li><a href="/erste-schritte/was-ist-apptivegrid">Was ist ApptiveGrid</a></li><li><a href="/fehlerbehebung/haeufige-fehlermeldungen">Häufige Fehlermeldungen</a></li></ul>',56)])])}const m=n(a,[["render",d]]);export{c as __pageData,m as default};
